def lever_rule(C0=None, C1=None, C2=None, mass=None):
    """Phase fractions by the lever rule. The mass fractions (and masses) of the two phases of an alloy of overall composition C0 in a two-phase region whose tie line ends at C1 and C2.
    Formula: W_1 = \\frac{C_2-C_0}{C_2-C_1},\\quad W_2 = \\frac{C_0-C_1}{C_2-C_1}
    Inputs:
        C0: overall composition (wt%)
        C1: composition of phase 1 (wt%)
        C2: composition of phase 2 (wt%)
        mass: total mass of the alloy (optional) (optional)
    Outputs: W1 (mass fraction of phase 1), W2 (mass fraction of phase 2), m1 (mass of phase 1), m2 (mass of phase 2)
    See also: help("lever_rule")
    """
    given = {k: v for k, v in dict(C0=C0, C1=C1, C2=C2, mass=mass).items() if v is not None}
    return _P.solve("lever_rule", **given)

def linear_density(structure=None, u=None, v=None, w=None, a=None):
    """Linear density along a crystal direction. The number of atoms per unit length along the [u v w] direction of an SC, BCC or FCC crystal, and the linear packing fraction.
    Formula: \\mathrm{LD} = \\frac{\\text{atoms centred on the line}}{\\text{length of the line}}
    Inputs:
        structure: crystal structure (SC, BCC, FCC)
        u: direction index u
        v: direction index v
        w: direction index w
        a: lattice parameter
    Outputs: LD_per_nm (atoms per nm along [uvw]), LD (atoms per metre along [uvw]), repeat_nm (repeat distance along [uvw] in nm), LPF (linear packing fraction (hard spheres))
    See also: help("linear_density")
    """
    given = {k: v for k, v in dict(structure=structure, u=u, v=v, w=w, a=a).items() if v is not None}
    return _P.solve("linear_density", **given)

def linear_thermal_expansion(alpha=None, L0=None, dT=None):
    """Linear thermal expansion. The length change dL = alpha L0 dT and the new length of a bar heated or cooled freely by dT.
    Formula: \\Delta L = \\alpha L_0\\,\\Delta T
    Inputs:
        alpha: linear thermal expansion coefficient
        L0: initial length
        dT: temperature change (positive = heating)
    Outputs: dL (length change), dL_mm (length change in mm), L (new length), strain (thermal strain alpha dT)
    See also: help("linear_thermal_expansion")
    """
    given = {k: v for k, v in dict(alpha=alpha, L0=L0, dT=dT).items() if v is not None}
    return _P.solve("linear_thermal_expansion", **given)

def max_schmid_factor(structure=None, load=None, tau_crss=None):
    """Most favourable slip system of an FCC or BCC crystal. The largest Schmid factor over the 12 {111}<110> (FCC) or {110}<111> (BCC) slip systems for a tensile load direction, how many systems share it, and the yield stress from the CRSS.
    Formula: m = \\max_{\\text{systems}}|\\cos\\phi\\cos\\lambda|
    Inputs:
        structure: crystal structure (FCC, BCC)
        load: loading direction [u v w]
        tau_crss: critical resolved shear stress (optional) (optional)
    Outputs: max_schmid_factor (largest Schmid factor), active_systems (number of systems with that factor), systems (slip systems considered), yield_MPa (tensile yield stress in MPa)
    See also: help("max_schmid_factor")
    """
    given = {k: v for k, v in dict(structure=structure, load=load, tau_crss=tau_crss).items() if v is not None}
    return _P.solve("max_schmid_factor", **given)

def maxwell_stress_relaxation(sigma0=None, E=None, eta=None, t=None):
    """Stress relaxation of a Maxwell viscoelastic solid. The stress remaining after time t in a polymer held at constant strain, modelled as a Maxwell element: sigma(t) = sigma_0 exp(-t E/eta).
    Formula: \\sigma(t) = \\sigma_0 e^{-t/\\tau},\\quad \\tau = \\frac{\\eta}{E}
    Inputs:
        sigma0: initial stress
        E: spring modulus
        eta: dashpot viscosity
        t: time held
    Outputs: sigma_t (stress at time t), sigma_t_MPa (stress at time t in MPa), tau (relaxation time eta/E), ratio (sigma(t)/sigma_0)
    See also: help("maxwell_stress_relaxation")
    """
    given = {k: v for k, v in dict(sigma0=sigma0, E=E, eta=eta, t=t).items() if v is not None}
    return _P.solve("maxwell_stress_relaxation", **given)

def miller_bravais_direction(U=None, V=None, W=None):
    """Three-index to four-index (Miller-Bravais) direction. Convert a hexagonal direction [U V W] (axes a1, a2, c) to the Miller-Bravais form [u v t w] (axes a1, a2, a3, c).
    Formula: u = \\tfrac13(2U-V),\\ v = \\tfrac13(2V-U),\\ t = -(u+v),\\ w = W
    Inputs:
        U: index along a1
        V: index along a2
        W: index along c
    Outputs: u (Miller-Bravais index u), v (Miller-Bravais index v), t (Miller-Bravais index t), w (Miller-Bravais index w), indices ([u v t w])
    See also: help("miller_bravais_direction")
    """
    given = {k: v for k, v in dict(U=U, V=V, W=W).items() if v is not None}
    return _P.solve("miller_bravais_direction", **given)

def miller_bravais_to_three_index(u=None, v=None, t=None, w=None):
    """Four-index (Miller-Bravais) to three-index direction. Convert a Miller-Bravais direction [u v t w] of a hexagonal crystal to the three-index form [U V W].
    Formula: U = u - t,\\ V = v - t,\\ W = w
    Inputs:
        u: index along a1
        v: index along a2
        t: index along a3 (= -(u + v))
        w: index along c
    Outputs: U (three-index component U), V (three-index component V), W (three-index component W), indices ([U V W])
    See also: help("miller_bravais_to_three_index")
    """
    given = {k: v for k, v in dict(u=u, v=v, t=t, w=w).items() if v is not None}
    return _P.solve("miller_bravais_to_three_index", **given)

def miller_indices_from_intercepts(x=None, y=None, z=None):
    """Miller indices of a plane from its intercepts. The Miller indices (h k l) of a plane cutting the axes at x, y, z (in units of the cell edges; inf for a plane parallel to an axis).
    Formula: (hkl) \\propto \\left(\\tfrac1x, \\tfrac1y, \\tfrac1z\\right)
    Inputs:
        x: intercept on the a axis (number, fraction or inf)
        y: intercept on the b axis
        z: intercept on the c axis
    Outputs: h (Miller index h), k (Miller index k), l (Miller index l), indices ((h k l))
    See also: help("miller_indices_from_intercepts")
    """
    given = {k: v for k, v in dict(x=x, y=y, z=z).items() if v is not None}
    return _P.solve("miller_indices_from_intercepts", **given)

def modulus_of_resilience(sy=None, E=None):
    """Modulus of resilience. The elastic strain energy per unit volume stored up to yielding: U_r = sigma_y^2/(2E).
    Formula: U_r = \\frac{\\sigma_y^2}{2E}
    Inputs:
        sy: yield strength
        E: Young's modulus
    Outputs: Ur (modulus of resilience), Ur_MJ_m3 (modulus of resilience in MJ/m^3 (= MPa)), yield_strain (strain at yield)
    See also: help("modulus_of_resilience")
    """
    given = {k: v for k, v in dict(sy=sy, E=E).items() if v is not None}
    return _P.solve("modulus_of_resilience", **given)

def molecular_weight_averages(M=None, fraction=None, basis=None):
    """Number- and weight-average molecular weight and dispersity. Mn, Mw and the dispersity Mw/Mn of a polymer from a molecular-weight distribution given as number fractions or weight fractions per size range.
    Formula: \\bar M_n = \\sum x_iM_i,\\quad \\bar M_w = \\sum w_iM_i,\\quad \\mathrm{PDI} = \\bar M_w/\\bar M_n
    Inputs:
        M: mean molecular weight of each size range in g/mol
        fraction: number or weight fraction of each range (normalised)
        basis: whether the fractions are number (x_i) or weight (w_i) fractions (default number) (optional)
    Outputs: Mn (number-average molecular weight in g/mol), Mw (weight-average molecular weight in g/mol), PDI (dispersity (polydispersity index) Mw/Mn)
    See also: help("molecular_weight_averages")
    """
    given = {k: v for k, v in dict(M=M, fraction=fraction, basis=basis).items() if v is not None}
    return _P.solve("molecular_weight_averages", **given)

def offset_yield_strength(strain=None, stress=None, E=None, offset=None):
    """0.2 % offset yield strength from a stress-strain curve. The yield strength where the stress-strain curve (piecewise linear through the data) meets a line of slope E offset by 0.2 % strain (or another offset).
    Formula: \\sigma(\\varepsilon_y) = E(\\varepsilon_y - 0.002)
    Inputs:
        strain: engineering strains, increasing
        stress: engineering stresses in MPa
        E: Young's modulus
        offset: strain offset (default 0.002) (optional)
    Outputs: yield_MPa (offset yield strength in MPa), yield_strain (strain at the intersection)
    See also: help("offset_yield_strength")
    """
    given = {k: v for k, v in dict(strain=strain, stress=stress, E=E, offset=offset).items() if v is not None}
    return _P.solve("offset_yield_strength", **given)

def planar_density(structure=None, h=None, k=None, l=None, a=None):
    """Planar density of a crystal plane. The number of atoms per unit area on the (h k l) plane of an SC, BCC or FCC crystal, and the planar packing fraction.
    Formula: \\mathrm{PD} = n_V\\,d_{\\mathrm{planes}},\\quad \\mathrm{PPF} = \\mathrm{PD}\\,\\pi R^2
    Inputs:
        structure: crystal structure (SC, BCC, FCC)
        h: Miller index h
        k: Miller index k
        l: Miller index l
        a: lattice parameter
    Outputs: PD_per_nm2 (atoms per nm^2 on the plane), PD (atoms per m^2 on the plane), PPF (planar packing fraction (hard spheres))
    See also: help("planar_density")
    """
    given = {k: v for k, v in dict(structure=structure, h=h, k=k, l=l, a=a).items() if v is not None}
    return _P.solve("planar_density", **given)

def pn_junction_built_in_potential(Na=None, Nd=None, ni=None, T=None, eps_r=None):
    """Built-in potential of a p-n junction. The built-in potential V_bi = (kT/q) ln(n_n p_p/ni^2) of an abrupt p-n junction (majority concentrations from charge neutrality; V_bi ~ (kT/q) ln(Na Nd/ni^2) when Na, Nd >> ni), and with a permittivity the zero-bias depletion width.
    Formula: V_{bi} = \\frac{kT}{q}\\ln\\frac{N_aN_d}{n_i^2},\\quad W = \\sqrt{\\frac{2\\varepsilon V_{bi}}{q}\\left(\\frac{1}{N_a} + \\frac{1}{N_d}\\right)}
    Inputs:
        Na: acceptor concentration on the p side
        Nd: donor concentration on the n side
        ni: intrinsic carrier concentration
        T: temperature
        eps_r: relative permittivity of the semiconductor (optional, for the depletion width) (optional)
    Outputs: V_bi (built-in potential), V_bi_approx ((kT/q) ln(Na Nd/ni^2)), thermal_voltage (kT/q), W (zero-bias depletion width), W_um (depletion width in um), x_n_um (depletion width on the n side in um), x_p_um (depletion width on the p side in um)
    See also: help("pn_junction_built_in_potential")
    """
    given = {k: v for k, v in dict(Na=Na, Nd=Nd, ni=ni, T=T, eps_r=eps_r).items() if v is not None}
    return _P.solve("pn_junction_built_in_potential", **given)

def polymer_chain_dimensions(n=None, l=None, theta=None):
    """End-to-end distance of a freely rotating chain. The root-mean-square end-to-end distance and characteristic ratio of a polymer chain of n bonds of length l with fixed bond angle and free rotation, and its all-trans contour length.
    Formula: \\langle r^2\\rangle = nl^2\\left[\\frac{1+c}{1-c} - \\frac{2c(1-c^n)}{n(1-c)^2}\\right],\\ c = -\\cos\\theta
    Inputs:
        n: number of backbone bonds
        l: bond length
        theta: bond angle in degrees (default 109.47, tetrahedral) (optional)
    Outputs: r_rms (rms end-to-end distance), r_rms_nm (rms end-to-end distance in nm), C_n (characteristic ratio <r^2>/(n l^2)), contour_nm (all-trans contour length in nm)
    See also: help("polymer_chain_dimensions")
    """
    given = {k: v for k, v in dict(n=n, l=l, theta=theta).items() if v is not None}
    return _P.solve("polymer_chain_dimensions", **given)

def polymer_crystallinity(rho_s=None, rho_c=None, rho_a=None):
    """Percent crystallinity of a polymer from densities. The mass percent crystallinity of a semicrystalline polymer from its density and the densities of the fully crystalline and fully amorphous polymer.
    Formula: \\%\\,\\text{cryst} = \\frac{\\rho_c(\\rho_s-\\rho_a)}{\\rho_s(\\rho_c-\\rho_a)}\\times100
    Inputs:
        rho_s: density of the sample
        rho_c: density of the totally crystalline polymer
        rho_a: density of the totally amorphous polymer
    Outputs: crystallinity_percent (percent crystallinity (by mass))
    See also: help("polymer_crystallinity")
    """
    given = {k: v for k, v in dict(rho_s=rho_s, rho_c=rho_c, rho_a=rho_a).items() if v is not None}
    return _P.solve("polymer_crystallinity", **given)

def polymorphic_volume_change(R_bcc=None, R_fcc=None):
    """Volume change of a BCC to FCC transformation. The percentage volume change when a metal transforms from BCC to FCC (as iron at 912 C), from the atomic radius in each structure.
    Formula: \\frac{\\Delta V}{V} = \\frac{a_F^3/4 - a_B^3/2}{a_B^3/2}
    Inputs:
        R_bcc: atomic radius in the BCC form
        R_fcc: atomic radius in the FCC form
    Outputs: volume_change_percent (volume change BCC -> FCC in percent (negative = contraction)), V_atom_bcc_nm3 (volume per atom in BCC, nm^3), V_atom_fcc_nm3 (volume per atom in FCC, nm^3)
    See also: help("polymorphic_volume_change")
    """
    given = {k: v for k, v in dict(R_bcc=R_bcc, R_fcc=R_fcc).items() if v is not None}
    return _P.solve("polymorphic_volume_change", **given)

def radius_ratio_coordination(rc=None, ra=None):
    """Coordination number from the cation-anion radius ratio. The expected coordination number and polyhedron of a cation from the ratio of the cation and anion radii (Pauling's radius-ratio rule).
    Formula: \\frac{r_c}{r_a}:\\ 0.155\\ (3),\\ 0.225\\ (4),\\ 0.414\\ (6),\\ 0.732\\ (8)
    Inputs:
        rc: cation radius
        ra: anion radius
    Outputs: ratio (rc/ra), CN (coordination number), geometry (coordination polyhedron)
    See also: help("radius_ratio_coordination")
    """
    given = {k: v for k, v in dict(rc=rc, ra=ra).items() if v is not None}
    return _P.solve("radius_ratio_coordination", **given)

def rubber_elasticity(rho=None, Mc=None, T=None, stretch=None):
    """Stress in a stretched rubber (affine network). The shear modulus G = rho R T / Mc of a crosslinked rubber and its engineering and true stress at a uniaxial stretch ratio lambda.
    Formula: \\sigma = \\frac{\\rho RT}{M_c}\\left(\\lambda - \\frac{1}{\\lambda^2}\\right)
    Inputs:
        rho: density of the rubber
        Mc: molecular weight between crosslinks
        T: temperature
        stretch: stretch ratio lambda = L/L0
    Outputs: G_MPa (shear modulus in MPa), stress_MPa (engineering stress in MPa), true_stress_MPa (true stress in MPa)
    See also: help("rubber_elasticity")
    """
    given = {k: v for k, v in dict(rho=rho, Mc=Mc, T=T, stretch=stretch).items() if v is not None}
    return _P.solve("rubber_elasticity", **given)

def schmid_factor(load=None, plane=None, direction=None, sigma=None, tau_crss=None):
    """Resolved shear stress and Schmid factor of a slip system. The Schmid factor cos(phi) cos(lambda) of a slip system (plane normal and slip direction) for a tensile load along a direction of a cubic crystal, the resolved shear stress and the stress to start slip.
    Formula: \\tau_R = \\sigma\\cos\\phi\\cos\\lambda,\\quad \\sigma_y = \\frac{\\tau_{\\mathrm{crss}}}{\\cos\\phi\\cos\\lambda}
    Inputs:
        load: loading direction [u v w]
        plane: slip-plane normal (h k l)
        direction: slip direction [u v w]
        sigma: applied tensile stress (optional) (optional)
        tau_crss: critical resolved shear stress (optional) (optional)
    Outputs: schmid_factor (|cos(phi) cos(lambda)|), phi_deg (angle between load and plane normal), lambda_deg (angle between load and slip direction), tau_R_MPa (resolved shear stress in MPa), yield_MPa (tensile stress at which slip starts, in MPa)
    See also: help("schmid_factor")
    """
    given = {k: v for k, v in dict(load=load, plane=plane, direction=direction, sigma=sigma, tau_crss=tau_crss).items() if v is not None}
    return _P.solve("schmid_factor", **given)

def space_group(structure=None):
    """Space group of a common crystal structure. The space-group number, Hermann-Mauguin symbol and crystal system of a common metallic or ionic structure.
    Formula: \\text{e.g. FCC: } Fm\\bar{3}m\\ (225)
    Inputs:
        structure: structure (SC, BCC, FCC, HCP, diamond, rocksalt, CsCl, zincblende, fluorite)
    Outputs: number (space-group number (International Tables)), symbol (Hermann-Mauguin symbol), crystal_system (crystal system)
    See also: help("space_group")
    """
    given = {k: v for k, v in dict(structure=structure).items() if v is not None}
    return _P.solve("space_group", **given)

def strain_hardening_exponent(true_strain=None, true_stress=None, strain_target=None):
    """Strain-hardening exponent and strength coefficient (Hollomon). The strain-hardening exponent n and strength coefficient K of sigma_T = K epsilon_T^n from true stress-strain points of the plastic region, and the stress at another strain.
    Formula: \\ln\\sigma_T = \\ln K + n\\ln\\varepsilon_T
    Inputs:
        true_strain: true plastic strains
        true_stress: true stresses in MPa
        strain_target: true strain at which the stress is wanted (optional) (optional)
    Outputs: n (strain-hardening exponent), K_MPa (strength coefficient in MPa), r_squared (r^2 of the log-log fit), stress_target_MPa (true stress at the target strain in MPa)
    See also: help("strain_hardening_exponent")
    """
    given = {k: v for k, v in dict(true_strain=true_strain, true_stress=true_stress, strain_target=strain_target).items() if v is not None}
    return _P.solve("strain_hardening_exponent", **given)

def structure_factor_cubic(structure=None, h=None, k=None, l=None):
    """Structure factor and extinction of a cubic reflection. The structure factor |F|/f of the (h k l) reflection of a monatomic SC, BCC, FCC or diamond-cubic crystal, and whether the reflection is allowed.
    Formula: F_{hkl} = f\\sum_j e^{2\\pi i(hx_j+ky_j+lz_j)}
    Inputs:
        structure: crystal structure (SC, BCC, FCC, diamond)
        h: Miller index h
        k: Miller index k
        l: Miller index l
    Outputs: F_over_f (|F| in units of the atomic scattering factor f), F2_over_f2 (|F|^2 / f^2 (proportional to intensity)), allowed (whether the reflection appears)
    See also: help("structure_factor_cubic")
    """
    given = {k: v for k, v in dict(structure=structure, h=h, k=k, l=l).items() if v is not None}
    return _P.solve("structure_factor_cubic", **given)

def tensile_toughness(strain=None, stress=None):
    """Toughness (area under the stress-strain curve). The energy absorbed per unit volume up to fracture (trapezoidal area under the stress-strain data), the tensile strength and the fracture strain.
    Formula: U_T = \\int_0^{\\varepsilon_f}\\sigma\\,d\\varepsilon
    Inputs:
        strain: engineering strains, non-decreasing
        stress: engineering stresses in MPa
    Outputs: toughness_MJ_m3 (toughness in MJ/m^3), toughness (toughness), uts_MPa (tensile strength (largest stress) in MPa), fracture_strain (strain at the last point)
    See also: help("tensile_toughness")
    """
    given = {k: v for k, v in dict(strain=strain, stress=stress).items() if v is not None}
    return _P.solve("tensile_toughness", **given)

def theoretical_density(structure=None, A=None, R=None):
    """Theoretical density of a metal. The density of a crystal from its structure, the atomic radius and the molar mass: rho = n A / (V_cell N_A).
    Formula: \\rho = \\frac{n A}{V_{\\mathrm{cell}} N_A}
    Inputs:
        structure: crystal structure (SC, BCC, FCC, HCP, diamond)
        A: molar mass (atomic weight)
        R: atomic radius
    Outputs: rho (theoretical density), rho_gcc (density in g/cm^3), a_nm (lattice parameter a in nm)
    See also: help("theoretical_density")
    """
    given = {k: v for k, v in dict(structure=structure, A=A, R=R).items() if v is not None}
    return _P.solve("theoretical_density", **given)

def thermal_stress(E=None, alpha=None, dT=None, constraint=None, nu=None):
    """Thermal stress in a constrained body. The stress from a temperature change in a body held in one direction (rod between walls), two (thin film or plate) or three (fully constrained).
    Formula: \\sigma = -E\\alpha\\Delta T,\\quad -\\frac{E\\alpha\\Delta T}{1-\\nu},\\quad -\\frac{E\\alpha\\Delta T}{1-2\\nu}
    Inputs:
        E: Young's modulus
        alpha: linear thermal expansion coefficient
        dT: temperature change (positive = heating)
        constraint: constraint (uniaxial, biaxial, triaxial; default uniaxial) (optional)
        nu: Poisson's ratio (needed for biaxial and triaxial) (optional)
    Outputs: stress (thermal stress (negative = compression)), stress_MPa (thermal stress in MPa)
    See also: help("thermal_stress")
    """
    given = {k: v for k, v in dict(E=E, alpha=alpha, dT=dT, constraint=constraint, nu=nu).items() if v is not None}
    return _P.solve("thermal_stress", **given)

def true_stress_and_strain(stress=None, strain=None):
    """True stress and true strain from engineering values. True stress and true strain from the engineering stress and strain of a tensile test before necking (volume conserved).
    Formula: \\sigma_T = \\sigma(1+\\varepsilon),\\quad \\varepsilon_T = \\ln(1+\\varepsilon)
    Inputs:
        stress: engineering stress
        strain: engineering strain (dimensionless)
    Outputs: true_stress (true stress), true_stress_MPa (true stress in MPa), true_strain (true strain)
    See also: help("true_stress_and_strain")
    """
    given = {k: v for k, v in dict(stress=stress, strain=strain).items() if v is not None}
    return _P.solve("true_stress_and_strain", **given)

def unit_cell_volume(a=None, b=None, c=None, alpha=None, beta=None, gamma=None):
    """Volume of a general (triclinic) unit cell. The volume of a unit cell from its six lattice parameters a, b, c, alpha, beta, gamma.
    Formula: V = abc\\sqrt{1-\\cos^2\\alpha-\\cos^2\\beta-\\cos^2\\gamma+2\\cos\\alpha\\cos\\beta\\cos\\gamma}
    Inputs:
        a: cell edge a
        b: cell edge b
        c: cell edge c
        alpha: cell angle alpha in degrees (between b and c)
        beta: cell angle beta in degrees (between a and c)
        gamma: cell angle gamma in degrees (between a and b)
    Outputs: V (cell volume), V_nm3 (cell volume in nm^3)
    See also: help("unit_cell_volume")
    """
    given = {k: v for k, v in dict(a=a, b=b, c=c, alpha=alpha, beta=beta, gamma=gamma).items() if v is not None}
    return _P.solve("unit_cell_volume", **given)

def vacancy_concentration(rho=None, A=None, Qv=None, T=None):
    """Equilibrium vacancy concentration. The number of atomic sites per volume and the equilibrium number of vacancies N_v = N exp(-Q_v/kT) of a metal.
    Formula: N_v = N\\exp\\!\\left(-\\frac{Q_v}{kT}\\right),\\quad N = \\frac{N_A\\rho}{A}
    Inputs:
        rho: density
        A: molar mass
        Qv: vacancy formation energy (per vacancy, e.g. eV)
        T: temperature
    Outputs: N (atomic sites per volume), Nv (vacancies per volume), fraction (vacancy fraction Nv/N), log10_Nv (log10 of Nv in m^-3), N_per_cm3 (atomic sites per cm^3)
    See also: help("vacancy_concentration")
    """
    given = {k: v for k, v in dict(rho=rho, A=A, Qv=Qv, T=T).items() if v is not None}
    return _P.solve("vacancy_concentration", **given)

def vacancy_formation_energy_fit(T=None, fraction=None):
    """Vacancy formation energy from vacancy fractions. The vacancy formation energy Q_v and prefactor from vacancy fractions measured at two or more temperatures (least-squares Arrhenius line).
    Formula: \\ln\\frac{N_v}{N} = \\ln C - \\frac{Q_v}{k}\\frac1T
    Inputs:
        T: temperatures in kelvin
        fraction: vacancy fractions N_v/N at those temperatures
    Outputs: Qv_eV (vacancy formation energy in eV), Qv (vacancy formation energy), prefactor (prefactor C of N_v/N = C exp(-Q_v/kT)), r_squared (r^2 of the fit)
    See also: help("vacancy_formation_energy_fit")
    """
    given = {k: v for k, v in dict(T=T, fraction=fraction).items() if v is not None}
    return _P.solve("vacancy_formation_energy_fit", **given)

def volumetric_thermal_expansion(alpha=None, V0=None, dT=None):
    """Volumetric thermal expansion. The volume change dV = beta V0 dT of an isotropic solid with beta = 3 alpha (linearised), and the exact change V0((1 + alpha dT)^3 - 1).
    Formula: \\Delta V = \\beta V_0\\,\\Delta T,\\quad \\beta = 3\\alpha
    Inputs:
        alpha: LINEAR thermal expansion coefficient
        V0: initial volume
        dT: temperature change (positive = heating)
    Outputs: beta (volumetric coefficient 3 alpha), dV (linearised volume change beta V0 dT), dV_cm3 (linearised volume change in cm^3), V (new volume (linearised)), dV_exact (exact volume change V0((1 + alpha dT)^3 - 1)), dV_exact_cm3 (exact volume change in cm^3)
    See also: help("volumetric_thermal_expansion")
    """
    given = {k: v for k, v in dict(alpha=alpha, V0=V0, dT=dT).items() if v is not None}
    return _P.solve("volumetric_thermal_expansion", **given)

def weibull_design_stress(P_failure=None, sigma0=None, m=None, V_ratio=None):
    """Design stress for a target failure probability (Weibull). The stress at which a brittle part reaches a given failure probability, from the Weibull modulus and characteristic strength (and V/V0).
    Formula: \\sigma = \\sigma_0\\left[-\\frac{V_0}{V}\\ln(1-P_f)\\right]^{1/m}
    Inputs:
        P_failure: allowed probability of failure (0 to 1)
        sigma0: characteristic strength
        m: Weibull modulus
        V_ratio: V/V0 (default 1) (optional)
    Outputs: sigma (design stress), sigma_MPa (design stress in MPa)
    See also: help("weibull_design_stress")
    """
    given = {k: v for k, v in dict(P_failure=P_failure, sigma0=sigma0, m=m, V_ratio=V_ratio).items() if v is not None}
    return _P.solve("weibull_design_stress", **given)

def weibull_failure_probability(sigma=None, sigma0=None, m=None, V_ratio=None):
    """Weibull probability of failure of a brittle part. The probability that a brittle (ceramic) part fails at stress sigma, from the Weibull modulus m and characteristic strength sigma_0, with an optional volume ratio V/V0.
    Formula: P_f = 1 - \\exp\\!\\left[-\\frac{V}{V_0}\\left(\\frac{\\sigma}{\\sigma_0}\\right)^m\\right]
    Inputs:
        sigma: applied stress
        sigma0: characteristic strength (63.2 % failure at V0)
        m: Weibull modulus
        V_ratio: stressed volume over the reference volume V/V0 (default 1) (optional)
    Outputs: P_failure (probability of failure), P_survival (probability of survival)
    See also: help("weibull_failure_probability")
    """
    given = {k: v for k, v in dict(sigma=sigma, sigma0=sigma0, m=m, V_ratio=V_ratio).items() if v is not None}
    return _P.solve("weibull_failure_probability", **given)

def weibull_modulus_fit(strengths=None):
    """Weibull modulus from a set of measured strengths. The Weibull modulus m and characteristic strength sigma_0 from measured fracture strengths, by median-rank regression (Bernard's ranks).
    Formula: \\ln\\ln\\frac{1}{1-F_i} = m\\ln\\sigma_i - m\\ln\\sigma_0
    Inputs:
        strengths: fracture strengths (any one unit, e.g. MPa)
    Outputs: m (Weibull modulus), sigma0 (characteristic strength (unit of the data)), r_squared (r^2 of the fit)
    See also: help("weibull_modulus_fit")
    """
    given = {k: v for k, v in dict(strengths=strengths).items() if v is not None}
    return _P.solve("weibull_modulus_fit", **given)

def weight_to_atomic_percent(element1=None, element2=None, wt1=None):
    """Weight percent to atomic percent (binary alloy). Convert the composition of a binary alloy from weight percent to atomic percent.
    Formula: C_1' = \\frac{C_1A_2}{C_1A_2 + C_2A_1}\\times100
    Inputs:
        element1: symbol of element 1
        element2: symbol of element 2
        wt1: weight percent of element 1
    Outputs: at1 (atomic percent of element 1), at2 (atomic percent of element 2)
    See also: help("weight_to_atomic_percent")
    """
    given = {k: v for k, v in dict(element1=element1, element2=element2, wt1=wt1).items() if v is not None}
    return _P.solve("weight_to_atomic_percent", **given)

def wiedemann_franz(T=None, sigma=None, rho=None):
    """Electronic thermal conductivity of a metal (Wiedemann-Franz law). The electronic thermal conductivity kappa = L sigma T of a metal from its electrical conductivity (or resistivity) and temperature, with the Sommerfeld value of the Lorenz number.
    Formula: \\kappa = L\\sigma T,\\quad L = \\frac{\\pi^2}{3}\\left(\\frac{k}{e}\\right)^2
    Inputs:
        T: temperature
        sigma: electrical conductivity (or give rho) (optional)
        rho: electrical resistivity (or give sigma) (optional)
    Outputs: kappa (thermal conductivity), lorenz (Lorenz number in W ohm/K^2)
    See also: help("wiedemann_franz")
    """
    given = {k: v for k, v in dict(T=T, sigma=sigma, rho=rho).items() if v is not None}
    return _P.solve("wiedemann_franz", **given)

def youngs_modulus_from_data(strain=None, stress=None):
    """Young's modulus from elastic stress-strain data. Young's modulus as the slope of the least-squares line through stress-strain points of the elastic region.
    Formula: E = \\frac{\\sum(\\varepsilon_i-\\bar\\varepsilon)(\\sigma_i-\\bar\\sigma)}{\\sum(\\varepsilon_i-\\bar\\varepsilon)^2}
    Inputs:
        strain: engineering strains (dimensionless)
        stress: engineering stresses in MPa
    Outputs: E_GPa (Young's modulus in GPa), E (Young's modulus), intercept_MPa (intercept of the line in MPa), r_squared (r^2 of the fit)
    See also: help("youngs_modulus_from_data")
    """
    given = {k: v for k, v in dict(strain=strain, stress=stress).items() if v is not None}
    return _P.solve("youngs_modulus_from_data", **given)


